(function(){var loadHandler=window['sl_{071A9F09-8EA0-44F0-B305-363C06242DE5}'];loadHandler&&loadHandler(68, '<div id="spr0_3718db"><div id="spr1_3718db" class="kern slide"><img id="img3_3718db" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_3718db" style="left:1192px;"><a id="hl0_3718db" href="#" onclick="document.getElementById(\'coreSpr_3557812\').getCore().processTriggerEffect(this);document.getElementById(\'coreSpr_3557812\').getCore().gotoFirstSlide(this);return false;"><img id="img0_3718db" src="data:image/png;base64," width="87" height="88" alt="" style="left:0.017px;top:0.102px;"/></a></div><div id="spr4_3718db" style="left:934.194px;top:5.036px;"><img id="img1_3718db" src="data:image/png;base64," width="277" height="67" alt="A close-up of a pen  AI-generated content may be incorrect." style="left:0.175px;top:0.101px;"/></div></div><div id="spr2_3718db" class="kern slide"><div id="spr5_3718db" style="left:9.231px;top:6.462px;"><div style="width:0px;"><span id="txt0_3718db" data-width="1080.778687" style="left:9.6px;top:-12.462px;">From the General Story to a Case Study</span></div></div><div id="spr6_3718db" style="left:9.231px;top:82.154px;"><div style="width:0px;"><span id="txt1_3718db" class="nokern relpos" dir="auto" style="left:9.6px;top:2.214px;">•</span> <span id="txt2_3718db" class="relpos" data-width="1125.377563" style="left:20.53px;top:-3.664px;">We have looked at colonisation across Africa in general. We will now</span></div><div style="width:0px;"><span id="txt3_3718db" class="relpos" data-width="99.895828" style="left:33.6px;top:36.656px;">study </span> <span id="txt4_3718db" class="relpos" data-width="523.085938" style="left:33.593px;top:36.656px;">one African kingdom in detail</span> <span id="txt5_3718db" class="relpos" style="left:33.587px;top:36.656px;">.</span></div><div style="width:0px;"><span id="txt6_3718db" class="nokern relpos" dir="auto" style="left:9.6px;top:95.485px;">•</span> <span id="txt7_3718db" class="relpos" data-width="70.437500" style="left:20.53px;top:89.606px;">The </span> <span id="txt8_3718db" class="relpos" data-width="564.666626" style="left:20.523px;top:89.606px;">Ashanti Kingdom of West Africa</span> <span id="txt9_3718db" class="relpos" data-width="530.979126" style="left:20.516px;top:89.606px;"> is a useful case study because it</span></div><div style="width:0px;"><span id="txt10_3718db" data-width="1169.091064" style="left:33.6px;top:130.629px;">was wealthy, politically organised and deeply involved in regional trade</span></div><div style="width:0px;"><span id="txt11_3718db" data-width="437.901031" style="left:33.6px;top:170.949px;">before British colonisation.</span></div><div style="width:0px;"><span id="txt12_3718db" class="nokern relpos" dir="auto" style="left:9.6px;top:229.779px;">•</span> <span id="txt13_3718db" class="relpos" data-width="554.750000" style="left:20.53px;top:223.9px;">The Ashanti controlled important </span> <span id="txt14_3718db" class="relpos" data-width="576.406250" style="left:20.523px;top:223.9px;">trade routes and gold-producing</span></div><div style="width:0px;"><span id="txt15_3718db" class="relpos" data-width="91.656250" style="left:33.6px;top:264.922px;">areas</span> <span id="txt16_3718db" class="relpos" style="left:33.593px;top:264.922px;">.</span></div><div style="width:0px;"><span id="txt17_3718db" class="nokern relpos" dir="auto" style="left:9.6px;top:323.752px;">•</span> <span id="txt18_3718db" class="relpos" data-width="1198.385376" style="left:20.53px;top:317.873px;">Their later resistance to Britain shows clearly that African societies fought</span></div><div style="width:0px;"><span id="txt19_3718db" class="relpos" data-width="256.356750" style="left:33.6px;top:358.896px;">to defend their </span> <span id="txt20_3718db" class="relpos" data-width="790.380188" style="left:33.593px;top:358.896px;">independence, political authority and culture</span> <span id="txt21_3718db" class="relpos" data-width="18.320313" style="left:33.587px;top:358.896px;">. </span></div><div style="width:0px;"><span id="txt22_3718db" class="nokern relpos" dir="auto" style="left:9.6px;top:418.833px;">•</span> <span id="txt23_3718db" class="relpos" data-width="142.458344" style="left:26.131px;top:415.474px;">Key Questions</span></div><div style="width:0px;"><span id="txt24_3718db" class="nokern relpos" data-width="14.109374" dir="auto" style="left:9.6px;top:452.452px;">1.</span> <span id="txt25_3718db" class="relpos" data-width="467.295563" style="left:19.491px;top:452.452px;">What was West Africa like before European colonisation?</span></div><div style="width:0px;"><span id="txt26_3718db" class="nokern relpos" data-width="14.109374" dir="auto" style="left:9.6px;top:485.945px;">2.</span> <span id="txt27_3718db" class="relpos" data-width="441.920563" style="left:19.491px;top:485.945px;">Why was the Ashanti Kingdom wealthy and powerful?</span></div><div style="width:0px;"><span id="txt28_3718db" class="nokern relpos" data-width="14.109374" dir="auto" style="left:9.6px;top:519.439px;">3.</span> <span id="txt29_3718db" class="relpos" data-width="432.751282" style="left:19.491px;top:519.439px;">How did relations with Europeans change over time?</span></div><div style="width:0px;"><span id="txt30_3718db" class="nokern relpos" data-width="14.109374" dir="auto" style="left:9.6px;top:552.932px;">4.</span> <span id="txt31_3718db" class="relpos" data-width="385.164063" style="left:19.491px;top:552.932px;">How did the Ashanti resist British colonisation?</span></div><div style="width:0px;"><span id="txt32_3718db" class="nokern relpos" data-width="14.109374" dir="auto" style="left:9.6px;top:586.425px;">5.</span> <span id="txt33_3718db" class="relpos" data-width="534.652344" style="left:19.491px;top:586.425px;">What were the results of colonisation for the Ashanti and Britain?</span></div></div><div id="spr7_3718db" style="left:1097px;top:443px;"><img id="img2_3718db" src="data:image/png;base64," width="181" height="271" alt=""/></div></div></div>', '{"s":[]}');})();